//! Run this consumer, then expand it to see the code generated by both macros.
use lab5_derive_macro_solution::{FieldSummary, timed};

// The consumer supplies the trait; the derive generates its implementation.
trait FieldSummary {
    fn summary() -> String;
}

#[derive(FieldSummary)]
#[allow(dead_code)]
struct Config {
    host: String,
    port: i32,
    #[summary(skip)]
    api_key: String,
}

#[timed]
fn compute(x: u32, y: u32) -> u32 {
    x * y + 1
}

#[timed]
fn classify(n: i32) -> &'static str {
    if n < 0 {
        return "negative";
    }
    if n == 0 {
        return "zero";
    }
    "positive"
}

#[timed]
async fn fetch(x: u32) -> u32 {
    std::future::ready(x * 2).await
}

fn main() {
    println!("summary: {}", Config::summary());
    let answer = compute(6, 7);
    assert_eq!(answer, 43);
    println!("compute: {answer}");

    let label = classify(-5);
    assert_eq!(label, "negative");
    println!("classify: {label}");

    let fetched = block_on(fetch(21));
    assert_eq!(fetched, 42);
    println!("fetch: {fetched}");
}

// A small standard-library executor for this demo. The real .await in fetch
// checks that the timing wrapper preserves an async context and return value.
// This is a test driver, not a networking or production executor framework.
fn block_on<F: std::future::Future>(future: F) -> F::Output {
    use std::sync::Arc;
    use std::task::{Context, Poll, Wake, Waker};
    use std::thread::{self, Thread};

    struct ThreadWaker(Thread);
    impl Wake for ThreadWaker {
        fn wake(self: Arc<Self>) {
            self.0.unpark();
        }
        fn wake_by_ref(self: &Arc<Self>) {
            self.0.unpark();
        }
    }

    let waker = Waker::from(Arc::new(ThreadWaker(thread::current())));
    let mut context = Context::from_waker(&waker);
    let mut future = std::pin::pin!(future);
    loop {
        match future.as_mut().poll(&mut context) {
            Poll::Ready(value) => return value,
            Poll::Pending => thread::park(),
        }
    }
}
